import json
import random
import string
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = 8099
KOD_UZUNLUK = 6
KARAKTERLER = string.ascii_lowercase + string.digits

kisaltmalar = {}


def kod_uret():
    while True:
        kod = "".join(random.choices(KARAKTERLER, k=KOD_UZUNLUK))
        if kod not in kisaltmalar:
            return kod


def _json_govde(veri):
    return json.dumps(veri).encode("utf-8")


class Servis(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def do_GET(self):
        yol = self.path.split("?", 1)[0].rstrip("/") or "/"
        if yol == "/saglik":
            self._cevap(200, {"durum": "ok"})
            return
        kod = yol[1:]
        url = kisaltmalar.get(kod)
        if url is None:
            self._cevap(404, {"hata": "kod bulunamadi"})
            return
        govde = _json_govde({"hata": "kod bulunamadi"})
        self.send_response(302)
        self.send_header("Location", url)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def do_POST(self):
        if self.path.split("?", 1)[0] != "/kisalt":
            self._cevap(404, {"hata": "bulunamadi"})
            return
        uzunluk = int(self.headers.get("Content-Length", 0))
        govde = self.rfile.read(uzunluk)
        try:
            url = json.loads(govde)["url"]
            if not isinstance(url, str) or not url.startswith(("http://", "https://")):
                raise ValueError
        except (json.JSONDecodeError, KeyError, ValueError):
            self._cevap(400, {"hata": "gecersiz istek"})
            return
        kod = kod_uret()
        kisaltmalar[kod] = url
        self._cevap(200, {"kod": kod})

    def _cevap(self, durum, veri):
        govde = _json_govde(veri)
        self.send_response(durum)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(govde)))
        self.end_headers()
        self.wfile.write(govde)

    def log_message(self, *args):
        pass


def main():
    sunucu = ThreadingHTTPServer(("", PORT), Servis)
    print(f"http://localhost:{PORT} dinleniyor...")
    try:
        sunucu.serve_forever()
    except KeyboardInterrupt:
        sunucu.server_close()


if __name__ == "__main__":
    main()

import json
import threading
import unittest
from http.server import ThreadingHTTPServer
from urllib import request as urlrequest
from urllib.error import HTTPError

import servis


class YonlendirmeTakipEtme(urlrequest.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


OPENER = urlrequest.build_opener(YonlendirmeTakipEtme)


def istek(adres, yol, govde=None):
    url = f"http://{adres}{yol}"
    veri = json.dumps(govde).encode("utf-8") if govde is not None else None
    req = urlrequest.Request(url, data=veri, method="POST" if veri is not None else "GET")
    try:
        with OPENER.open(req) as cevap:
            return cevap.status, dict(cevap.headers), cevap.read()
    except HTTPError as h:
        return h.code, dict(h.headers), h.read()


class ServisTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.sunucu = ThreadingHTTPServer(("127.0.0.1", 0), servis.Servis)
        cls.adres = f"{cls.sunucu.server_address[0]}:{cls.sunucu.server_address[1]}"
        cls.is_parcasi = threading.Thread(target=cls.sunucu.serve_forever, daemon=True)
        cls.is_parcasi.start()

    @classmethod
    def tearDownClass(cls):
        cls.sunucu.shutdown()
        cls.sunucu.server_close()

    def setUp(self):
        servis.kisaltmalar.clear()

    def test_saglik(self):
        durum, _, govde = istek(self.adres, "/saglik")
        self.assertEqual(durum, 200)
        self.assertEqual(json.loads(govde), {"durum": "ok"})

    def test_kisalt(self):
        durum, _, govde = istek(self.adres, "/kisalt", {"url": "https://ornek.com/sayfa"})
        self.assertEqual(durum, 200)
        sonuc = json.loads(govde)
        self.assertEqual(sonuc["kod"], servis.kisaltmalar.get(sonuc["kod"]) and sonuc["kod"])
        self.assertEqual(len(sonuc["kod"]), servis.KOD_UZUNLUK)
        self.assertEqual(servis.kisaltmalar[sonuc["kod"]], "https://ornek.com/sayfa")

    def test_yonlendirme(self):
        _, _, govde = istek(self.adres, "/kisalt", {"url": "https://ornek.com/hedef"})
        kod = json.loads(govde)["kod"]
        durum, basliklar, _ = istek(self.adres, f"/{kod}")
        self.assertEqual(durum, 302)
        self.assertEqual(basliklar["Location"], "https://ornek.com/hedef")

    def test_olmayan_kod_404(self):
        durum, _, _ = istek(self.adres, "/yokboylekod")
        self.assertEqual(durum, 404)

    def test_gecersiz_govde_400(self):
        durum, _, _ = istek(self.adres, "/kisalt", {"adres": "https://ornek.com"})
        self.assertEqual(durum, 400)
        durum, _, _ = istek(self.adres, "/kisalt", {"url": "ftp://ornek.com"})
        self.assertEqual(durum, 400)

    def test_bilinmeyen_404(self):
        durum, _, _ = istek(self.adres, "/olmayan/uc")
        self.assertEqual(durum, 404)


if __name__ == "__main__":
    unittest.main()

